<?php
declare(strict_types=1); namespace App\Http\Controllers\Classrooms; use App\Http\Controllers\Controller; use App\Http\Requests\Classrooms\MoveClassroomMemberRequest; use App\Models\{Classroom,ClassroomMembership}; use App\Services\Classrooms\ClassroomMembershipService; use Illuminate\Http\RedirectResponse; use Illuminate\View\View;
class ClassroomMemberMoveController extends Controller {public function edit(Classroom $classroom,ClassroomMembership $membership):View{request()->user()->can('classrooms.manage-students')?:abort(403);abort_unless($membership->classroom_id===$classroom->id,404);$targets=Classroom::where('academic_year_id',$classroom->academic_year_id)->where('is_active',true)->whereKeyNot($classroom->id)->with('gradeLevel')->get();return view('classrooms.move',compact('classroom','membership','targets'));}public function update(MoveClassroomMemberRequest $r,Classroom $classroom,ClassroomMembership $membership,ClassroomMembershipService $s):RedirectResponse{$target=Classroom::findOrFail($r->integer('target_classroom_id'));$s->move($r->user(),$membership,$target,$r->string('moved_at')->toString(),$r->input('notes'));return redirect()->route('classrooms.members.index',$target)->with('success','Siswa berhasil dipindahkan.');}}
